draw:
var m = p.mass;
var b = p.beta;
var g = 1 / Math.sqrt(1 - b * b);
var E = g * m;
var pc = g * b * m;

var padL = 46, padR = 16, padT = 16, padB = 32;
var axMax = Math.max(m * 4.2, 120);
var X = function (v) { return padL + v / axMax * (W - padL - padR); };
var Y = function (v) { return H - padB - v / axMax * (H - padT - padB); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(0), Y(axMax)); ctx.lineTo(X(0), Y(0)); ctx.lineTo(X(axMax), Y(0));
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("pc  (MeV)", (X(0) + X(axMax)) / 2, H - 8);
ctx.save();
ctx.translate(12, (Y(0) + Y(axMax)) / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("E  (MeV)", 0, 0);
ctx.restore();

// photon line E = pc
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(axMax), Y(axMax)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.textAlign = "right";
ctx.fillText("photon, E = pc", X(axMax) - 4, Y(axMax) + 16);

// mass shell E = sqrt((pc)^2 + (mc^2)^2)
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 160; i++) {
  var q = axMax * i / 160;
  var e = Math.sqrt(q * q + m * m);
  if (i === 0) ctx.moveTo(X(q), Y(e)); else ctx.lineTo(X(q), Y(e));
}
ctx.stroke();
ctx.lineWidth = 1;

// rest-mass intercept
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 3]);
ctx.beginPath(); ctx.moveTo(X(0), Y(m)); ctx.lineTo(X(axMax), Y(m)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("mc²", X(0) + 6, Y(m) - 6);

// the particle
ctx.strokeStyle = C.accent;
ctx.setLineDash([2, 3]);
ctx.beginPath();
ctx.moveTo(X(pc), Y(0)); ctx.lineTo(X(pc), Y(E)); ctx.lineTo(X(0), Y(E));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(pc), Y(E), 5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("this particle", X(pc) + 8, Y(E) - 8);

out.note = "mc² = " + m.toFixed(1) + " MeV,  beta = " + b.toFixed(3) +
  ",  gamma = " + g.toFixed(3) + "   |   E = " + E.toFixed(1) +
  " MeV,  pc = " + pc.toFixed(1) + " MeV,  K = " + (E - m).toFixed(1) + " MeV";

var mp = 938.3;
var K = p.kinetic;
var E = K + mp;
var sFixed = Math.sqrt(2 * mp * (E + mp));
var sCollide = 2 * E;
var barMax = 2 * (8000 + mp) * 1.02;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

var x0 = W * 0.06, x1 = W * 0.94;
var barW = x1 - x0;
var f = (t % 2.2) / 2.2;

function scene(yLine, yBar, label, sval, moving2) {
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(x0, yLine); ctx.lineTo(x1, yLine); ctx.stroke();

  var mid = (x0 + x1) / 2;
  var xa = x0 + (mid - x0 - 8) * f;
  var xb = moving2 ? x1 - (x1 - mid - 8) * f : mid + 10;

  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(xa, yLine, 6, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = moving2 ? C.accent : C.figure;
  ctx.beginPath(); ctx.arc(xb, yLine, 6, 0, Math.PI * 2); ctx.fill();

  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(label, x0, yLine - 16);

  ctx.fillStyle = C.faint;
  ctx.textAlign = "center";
  ctx.fillText(moving2 ? "both beams move" : "target at rest", (x0 + x1) / 2, yLine + 20);

  // bar
  var wBar = barW * sval / barMax;
  ctx.fillStyle = C.figure;
  ctx.fillRect(x0, yBar, wBar, 12);
  ctx.strokeStyle = C.rule;
  ctx.strokeRect(x0, yBar, barW, 12);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText("sqrt(s) = " + sval.toFixed(0) + " MeV", x0 + 2, yBar + 26);
}

// threshold markers drawn across both bars
function marker(val, name, yTop, yBot) {
  var xm = x0 + barW * val / barMax;
  ctx.strokeStyle = C.accent;
  ctx.setLineDash([3, 3]);
  ctx.beginPath(); ctx.moveTo(xm, yTop); ctx.lineTo(xm, yBot); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText(name, xm, yTop - 4);
}

scene(H * 0.20, H * 0.34, "Fixed target:  beam on hydrogen", sFixed, false);
scene(H * 0.66, H * 0.80, "Collider:  equal and opposite beams", sCollide, true);

marker(2 * mp + 135.0, "pi⁰", H * 0.30, H * 0.94);
marker(4 * mp, "p pbar", H * 0.30, H * 0.94);

out.note = "beam K = " + K.toFixed(0) + " MeV per proton   |   fixed target sqrt(s) = " +
  sFixed.toFixed(0) + " MeV,  collider sqrt(s) = " + sCollide.toFixed(0) +
  " MeV   |   ratio " + (sCollide / sFixed).toFixed(2);

var b = p.beta;
var th = p.angle * Math.PI / 180;
var g = 1 / Math.sqrt(1 - b * b);
var ratio = 1 / (g * (1 - b * Math.cos(th)));

var cs = W * 0.10;          // light speed in pixels per second
var vs = b * cs;
var T = 0.75;               // seconds between wavefronts
var loop = 7.0;
var tt = t % loop;
var yc = H * 0.52;
var xs = W * 0.10 + vs * tt;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// track
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, yc); ctx.lineTo(W, yc); ctx.stroke();

// wavefronts emitted in the past
ctx.strokeStyle = C.rule;
for (var k = 1; k <= 8; k++) {
  var te = tt - k * T;
  if (te < 0) continue;
  var xe = W * 0.10 + vs * te;
  var r = cs * (tt - te);
  ctx.beginPath(); ctx.arc(xe, yc, r, 0, Math.PI * 2); ctx.stroke();
}

// source
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(xs, yc, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("source", xs + 9, yc - 9);

// velocity arrow
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(xs, yc); ctx.lineTo(xs + 26, yc); ctx.stroke();
ctx.beginPath();
ctx.moveTo(xs + 26, yc); ctx.lineTo(xs + 19, yc - 4); ctx.lineTo(xs + 19, yc + 4);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();

// detector direction
var R = Math.min(W, H) * 0.36;
var dx = xs + R * Math.cos(th), dy = yc - R * Math.sin(th);
ctx.strokeStyle = C.figure;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(xs, yc); ctx.lineTo(dx, dy); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(dx, dy, 5, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("detector", dx, dy - 10);

// angle label
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.arc(xs, yc, 22, -th, 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("theta", xs + 26, yc - 16);

ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("crowded fronts ahead, stretched behind", 8, 16);

out.note = "beta = " + b.toFixed(2) + ",  gamma = " + g.toFixed(3) +
  ",  theta = " + p.angle.toFixed(0) + " deg   |   f / f0 = " + ratio.toFixed(3) +
  ",  lambda / lambda0 = " + (1 / ratio).toFixed(3) +
  (p.angle === 90 ? "   (transverse: pure time dilation)" : "");
